1: namespace StudentManagement.Core;
2: 
3: // COM-STU-001/003/008/009. Internal IDs stay Int64; Web adapters emit decimal strings.
4: public enum Role { Viewer, Staff, Administrator }
5: public enum Outcome { Saved, NoChange, ValidationFailed, Forbidden, NotFound, Conflict, ConfirmationRequired, SystemError, Unknown }
6: public sealed record CurrentUser(string Principal, string SessionId, Role Role);
7: public sealed record FieldError(string Field, string Code, string Message);
8: public sealed record BirthDateInput(string Era = "", string Year = "", string Month = "", string Day = "");
9: public sealed class StudentDraft
10: {
11:     public string StudentNo { get; set; } = "";
12:     public string StudentName { get; set; } = "";
13:     public string StudentNameKana { get; set; } = "";
14:     public BirthDateInput BirthDateInput { get; set; } = new();
15:     public string GenderCode { get; set; } = "0";
16:     public string PostalCode { get; set; } = "";
17:     public string PrefectureCode { get; set; } = "";
18:     public string AddressLine1 { get; set; } = "";
19:     public string? AddressLine2 { get; set; }
20:     public string? PhoneNumber { get; set; }
21:     public string? EmailAddress { get; set; }
22:     public string AdmissionDate { get; set; } = "";
23:     public string EnrollmentStatusCode { get; set; } = "01";
24:     public string? EnrollmentEndDate { get; set; }
25:     public long? ClassId { get; set; }
26:     public string? EmergencyContactName { get; set; }
27:     public string? RelationshipCode { get; set; }
28:     public string? EmergencyPhoneNumber { get; set; }
29:     public string? Remarks { get; set; }
30: }
31: public sealed class SearchCriteria
32: {
33:     public string? StudentNo { get; set; }
34:     public string? StudentName { get; set; }
35:     public string? StudentNameKana { get; set; }
36:     public int? SchoolYear { get; set; }
37:     public string? GradeCode { get; set; }
38:     public long? ClassId { get; set; }
39:     public bool UnassignedOnly { get; set; }
40:     public string[] EnrollmentStatusCodes { get; set; } = ["01", "02"];
41:     public string? PrefectureCode { get; set; }
42:     public string? PhoneNumber { get; set; }
43:     public string? AdmissionFrom { get; set; }
44:     public string? AdmissionTo { get; set; }
45:     public int Page { get; set; } = 1;
46:     public int PageSize { get; set; } = 20;
47:     public string SortKey { get; set; } = "studentNo";
48:     public string SortDirection { get; set; } = "asc";
49: }
50: public sealed record StudentRow(long StudentId, string StudentNo, string StudentName, string StudentNameKana,
51:     DateOnly BirthDate, int? SchoolYear, string? GradeName, string? ClassCode, string? ClassName,
52:     string? EnrollmentStatusName, string Address, string? PhoneNumber, DateOnly AdmissionDate,
53:     DateTimeOffset UpdatedAt, long RowVersion)
54: {
55:     public string BirthDateWareki => JapaneseDateService.ToWareki(BirthDate);
56: }
57: public sealed record SearchResult(Outcome Outcome, int Count, IReadOnlyList<StudentRow> Items,
58:     DateTimeOffset SearchedAt, bool LimitExceeded, IReadOnlyList<FieldError> Errors);
59: public sealed record StudentDetail(long StudentId, long RowVersion, StudentDraft Draft,
60:     DateOnly BirthDate, DateTimeOffset UpdatedAt, string UpdatedBy);
61: public sealed record CodeEntry(string CategoryId, string CodeValue, string CodeName, int DisplayOrder,
62:     bool IsActive, DateOnly ValidFrom, DateOnly? ValidTo, bool IsProtected);
63: public sealed record SchoolClass(long ClassId, int SchoolYear, string GradeCode, string ClassCode,
64:     string ClassName, DateOnly ValidFrom, DateOnly ValidTo, int? Capacity, int Occupied, bool IsActive);
65: public sealed record LookupSet(IReadOnlyList<CodeEntry> Codes, IReadOnlyList<SchoolClass> Classes);
66: public sealed record SaveRequest(StudentDraft Draft, long? StudentId = null, long? ExpectedVersion = null,
67:     int? SchoolYear = null, string? GradeCode = null, string? ConfirmationToken = null, string? Reason = null);
68: public sealed record SaveResult(Outcome Outcome, long? StudentId, long? RowVersion,
69:     IReadOnlyList<FieldError> Errors, string? ConfirmationToken = null,
70:     int CandidateCount = 0, IReadOnlyList<StudentRow>? Candidates = null, string? RequestId = null);
71: public interface IStudentService
72: {
73:     Task<SearchResult> SearchAsync(SearchCriteria criteria, CancellationToken ct = default);
74:     Task<StudentDetail?> GetAsync(long id, CancellationToken ct = default);
75:     Task<LookupSet> LookupAsync(CancellationToken ct = default);
76:     Task<LookupSet> LookupAsync(bool includeOccupancy,CancellationToken ct = default) => LookupAsync(ct);
77:     Task<SaveResult> SaveAsync(SaveRequest request, CancellationToken ct = default);
78:     Task<SaveResult> DeleteAsync(long id, long version, string reason, CancellationToken ct = default);
79: }
