39:     public SqlServerStudentService(string connectionString, Func<CurrentUser> currentUser, bool webTokens = false, TimeProvider? clock = null)
40:     {
41:         var builder = new SqlConnectionStringBuilder(connectionString) { Encrypt = SqlConnectionEncryptOption.Mandatory, TrustServerCertificate = false };
42:         _connectionString = builder.ConnectionString; _currentUser = currentUser; _webTokens = webTokens; _clock = clock ?? TimeProvider.System;
43:     }
44:     private DateTimeOffset Now => _clock.GetUtcNow();
45:     private static DateOnly BusinessDay(DateTimeOffset now) => DateOnly.FromDateTime(now.ToOffset(TimeSpan.FromHours(9)).DateTime);
46:     private CurrentUser User()
47:     {
48:         var user = _currentUser();
49:         StudentNormalizer.Text(user.Principal, 64, 64, "Principal", true);
50:         if (string.IsNullOrEmpty(user.SessionId) || !_webTokens && !Guid.TryParse(user.SessionId, out _)) throw new UnauthorizedAccessException("認証セッションが不正です。");
51:         return user;
52:     }
53:     private async Task<SqlConnection> Open(CancellationToken ct)
54:     {
55:         var connection = new SqlConnection(_connectionString);
56:         try {
57:             await connection.OpenAsync(ct);
58:             await using var diagnostic = connection.CreateCommand();
59:             diagnostic.CommandText = "SELECT snapshot_isolation_state FROM sys.databases WHERE database_id=DB_ID()";
60:             if (Convert.ToInt32(await diagnostic.ExecuteScalarAsync(ct), CultureInfo.InvariantCulture) != 1)
61:                 throw new InvalidOperationException("ALLOW_SNAPSHOT_ISOLATION ONが必要です。");
62:             return connection;
63:         } catch { await connection.DisposeAsync(); throw; }
64:     }
65:     internal static SqlCommand Command(SqlConnection connection, SqlTransaction? tx, string sql)
66:         => new(sql, connection, tx) { CommandTimeout = 30 };
67:     internal static void Param(SqlCommand command, string name, SqlDbType type, object? value, int size = 0)
68:     {
69:         if (value is DateOnly date) value = date.ToDateTime(TimeOnly.MinValue);
70:         var parameter = command.Parameters.Add(name, type);
71:         if (size != 0) parameter.Size = size;
72:         parameter.Value = value ?? DBNull.Value;
73:     }
74:     private static string? String(SqlDataReader reader, string column) => reader.IsDBNull(reader.GetOrdinal(column)) ? null : reader.GetString(reader.GetOrdinal(column));
75:     private static long Long(SqlDataReader reader, string column) => reader.GetInt64(reader.GetOrdinal(column));
76:     private static DateOnly Date(SqlDataReader reader, string column) => DateOnly.FromDateTime(reader.GetDateTime(reader.GetOrdinal(column)));
77:     private static StudentRow Row(SqlDataReader reader) => new(
78:         Long(reader,"student_id"), String(reader,"student_no")!, String(reader,"student_name")!, String(reader,"student_name_kana")!, Date(reader,"birth_date"),
79:         reader.IsDBNull(reader.GetOrdinal("school_year")) ? null : Convert.ToInt32(reader["school_year"]), String(reader,"grade_name"), String(reader,"class_code"), String(reader,"class_name"),
80:         String(reader,"status_name"), (String(reader,"prefecture_name") ?? "[不整合]") + String(reader,"address_line1"), String(reader,"phone_number"), Date(reader,"admission_date"),
81:         reader.GetFieldValue<DateTimeOffset>(reader.GetOrdinal("updated_at")), Long(reader,"row_version"));
82:     private const string RowSelect = """
83:         SELECT s.student_id,s.student_no,s.student_name,s.student_name_kana,s.birth_date,
84:                c.school_year,c.class_code,c.class_name,g.code_name grade_name,e.code_name status_name,
85:                p.code_name prefecture_name,s.address_line1,s.phone_number,s.admission_date,s.updated_at,s.row_version
86:           FROM dbo.m_student s
87:           LEFT JOIN dbo.m_class c ON c.class_id=s.class_id
88:           LEFT JOIN dbo.m_code g ON g.category_id=c.grade_category AND g.code_value=c.grade_code
89:           LEFT JOIN dbo.m_code e ON e.category_id=s.enrollment_category AND e.code_value=s.enrollment_status_code
90:           LEFT JOIN dbo.m_code p ON p.category_id=s.prefecture_category AND p.code_value=s.prefecture_code
91:         """;
92:     internal static async Task Gate(SqlConnection connection, SqlTransaction tx, CancellationToken ct)
93:     {
94:         await using var command = Command(connection,tx,"""
95:             SET XACT_ABORT ON;
96:             DECLARE @result int;
97:             EXEC @result=sys.sp_getapplock @Resource=N'test-project1:student-write',@LockMode='Exclusive',
98:                  @LockOwner='Transaction',@LockTimeout=5000,@DbPrincipal='public';
99:             IF @result<0 THROW 51001,N'保存用ロックを取得できませんでした。',1;
100:             """);
101:         await command.ExecuteNonQueryAsync(ct);
102:     }
103:     public async Task<SearchResult> SearchAsync(SearchCriteria criteria, CancellationToken ct = default)
104:     {
105:         _ = User(); var now = Now; var day = BusinessDay(now);
106:         try {
107:             if (criteria.Page < 1 || criteria.PageSize is not (20 or 50 or 100) || criteria.SortDirection is not ("asc" or "desc")) throw new ArgumentException("E-COM-003: ページ指定が不正です。");
108:             var order = criteria.SortKey switch { "studentNo" => "s.student_no", "name" => "s.name_key", "admissionDate" => "s.admission_date", "updatedAt" => "s.updated_at", _ => throw new ArgumentException("E-COM-003: 並び順が不正です。") };
109:             if (criteria.SchoolYear is < 1900 or > 9998 || criteria.ClassId is <= 0) throw new ArgumentException("E-DATE-003: 年度またはクラスが不正です。");
110:             if (criteria.UnassignedOnly && (criteria.SchoolYear is not null || criteria.GradeCode is not null || criteria.ClassId is not null)) throw new ArgumentException("E-SRC-001: 未所属と年度・学年・クラスは同時指定できません。");
111:             var statuses = criteria.EnrollmentStatusCodes;
112:             if (statuses.Length > 4 || statuses.Distinct(StringComparer.Ordinal).Count() != statuses.Length || statuses.Any(value => value is not ("01" or "02" or "03" or "04"))) throw new ArgumentException("E-STU-009: 在籍区分が不正です。");
113:             var no = string.IsNullOrEmpty(criteria.StudentNo) ? null : StudentNormalizer.Identifier(criteria.StudentNo,15,"StudentNo");
114:             var name = StudentNormalizer.Text(criteria.StudentName,8,8,"StudentName");
115:             name = name is null ? null : StudentNormalizer.NameKey(name);
116:             var kana = string.IsNullOrEmpty(criteria.StudentNameKana) ? null : StudentNormalizer.Kana(criteria.StudentNameKana,false).Replace(" ","");
117:             var phone = StudentNormalizer.Phone(criteria.PhoneNumber,"PhoneNumber");
118:             var grade = StudentNormalizer.Code(criteria.GradeCode,2,"GradeCode",false);
119:             var prefecture = StudentNormalizer.Code(criteria.PrefectureCode,2,"PrefectureCode",false);
120:             DateOnly? from = string.IsNullOrEmpty(criteria.AdmissionFrom) ? null : JapaneseDateService.ParseIso(criteria.AdmissionFrom,day);
121:             DateOnly? to = string.IsNullOrEmpty(criteria.AdmissionTo) ? null : JapaneseDateService.ParseIso(criteria.AdmissionTo,day);
122:             if (from > to) throw new ArgumentException("E-STU-006: 開始日は終了日以前にしてください。");
123:             await using var connection = await Open(ct);
124:             await using var tx = (SqlTransaction)await connection.BeginTransactionAsync(IsolationLevel.Snapshot,ct);
125:             if (grade is not null && !await CodeExists(connection,tx,"GRADE",grade,ct) || prefecture is not null && !await CodeExists(connection,tx,"PREFECTURE",prefecture,ct)) throw new ArgumentException("E-STU-009: 指定コードが存在しません。");
126:             if (criteria.SchoolYear is not null) {
127:                 await using var yearCheck = Command(connection,tx,"SELECT COUNT_BIG(*) FROM dbo.m_class WHERE school_year=@year");
128:                 Param(yearCheck,"@year",SqlDbType.SmallInt,criteria.SchoolYear);
129:                 if ((long)(await yearCheck.ExecuteScalarAsync(ct))! == 0) throw new ArgumentException("E-STU-014: 年度候補が存在しません。");
130:             }
131:             if (criteria.ClassId is { } classId) {
132:                 await using var classCheck = Command(connection,tx,"SELECT school_year,grade_code FROM dbo.m_class WHERE class_id=@id");
133:                 Param(classCheck,"@id",SqlDbType.BigInt,classId);
134:                 await using var reader = await classCheck.ExecuteReaderAsync(ct);
135:                 if (!await reader.ReadAsync(ct) || criteria.SchoolYear is not null && Convert.ToInt32(reader[0]) != criteria.SchoolYear || grade is not null && reader.GetString(1) != grade) throw new ArgumentException("E-STU-014: 年度・学年・クラスが一致しません。");
136:             }
137:             var predicates = new List<string>{ "s.is_deleted=0" };
138:             var parameters = new List<(string Name, SqlDbType Type, object? Value, int Size)>();
139:             void Where(string sql, string key, SqlDbType type, object? value, int size = 0) { if (value is not null) { predicates.Add(sql); parameters.Add((key,type,value,size)); } }
140:             Where("s.student_no LIKE @no ESCAPE '!'","@no",SqlDbType.VarChar,no is null ? null : StudentNormalizer.EscapeLike(no)+"%",31);
141:             Where("s.name_key LIKE @name ESCAPE '!'","@name",SqlDbType.NVarChar,name is null ? null : "%"+StudentNormalizer.EscapeLike(name)+"%",642);
142:             Where("s.kana_key LIKE @kana ESCAPE '!'","@kana",SqlDbType.NVarChar,kana is null ? null : "%"+StudentNormalizer.EscapeLike(kana)+"%",74);
143:             Where("c.school_year=@year","@year",SqlDbType.SmallInt,criteria.SchoolYear);
144:             Where("c.grade_code=@grade","@grade",SqlDbType.VarChar,grade,2);
145:             Where("s.class_id=@class","@class",SqlDbType.BigInt,criteria.ClassId);
146:             if(criteria.UnassignedOnly) predicates.Add("s.class_id IS NULL");
147:             Where("s.prefecture_code=@prefecture","@prefecture",SqlDbType.VarChar,prefecture,2);
148:             Where("(s.phone_number=@phone OR s.emergency_phone_number=@phone)","@phone",SqlDbType.VarChar,phone,16);
149:             Where("s.admission_date>=@from","@from",SqlDbType.Date,from);
150:             Where("s.admission_date<=@to","@to",SqlDbType.Date,to);
151:             if(statuses.Length>0) {
152:                 predicates.Add("s.enrollment_status_code IN ("+string.Join(',',statuses.Select((_,index)=>"@status"+index))+")");
153:                 parameters.AddRange(statuses.Select((value,index)=>("@status"+index,SqlDbType.VarChar,(object?)value,2)));
154:             }
155:             var where = " WHERE "+string.Join(" AND ",predicates);
156:             await using var countCommand = Command(connection,tx,"SELECT COUNT_BIG(*) FROM (SELECT TOP (10001) s.student_id FROM dbo.m_student s LEFT JOIN dbo.m_class c ON c.class_id=s.class_id"+where+") limited");
157:             foreach(var p in parameters) Param(countCommand,p.Name,p.Type,p.Value,p.Size);
158:             var count = (int)(long)(await countCommand.ExecuteScalarAsync(ct))!;
159:             if(count>10000) { await tx.CommitAsync(ct); return new(Outcome.NoChange,count,[],now,true,[]); }
160:             var lastPage = Math.Max(1,(count+criteria.PageSize-1)/criteria.PageSize);
161:             var page = Math.Min(criteria.Page,lastPage);
162:             await using var pageCommand = Command(connection,tx,RowSelect+where+" ORDER BY "+order+" "+criteria.SortDirection+",s.student_id ASC OFFSET @offset ROWS FETCH NEXT @size ROWS ONLY");
163:             foreach(var p in parameters) Param(pageCommand,p.Name,p.Type,p.Value,p.Size);
164:             Param(pageCommand,"@offset",SqlDbType.Int,checked((page-1)*criteria.PageSize)); Param(pageCommand,"@size",SqlDbType.Int,criteria.PageSize);
165:             var rows = new List<StudentRow>();
166:             await using(var reader = await pageCommand.ExecuteReaderAsync(ct)) while(await reader.ReadAsync(ct)) rows.Add(Row(reader));
167:             await tx.CommitAsync(ct);
168:             return new(Outcome.NoChange,count,rows,now,false,[]);
169:         } catch(InputValidationException e) { return new(Outcome.ValidationFailed,0,[],now,false,e.Errors); }
170:         catch(ArgumentException e) { return new(Outcome.ValidationFailed,0,[],now,false,[StudentNormalizer.ArgumentError("Search",e)]); }
171:     }
172:     public async Task<StudentDetail?> GetAsync(long id, CancellationToken ct = default)
173:     {
174:         _ = User(); if (id <= 0) return null;
175:         await using var connection = await Open(ct);
176:         await using var command = Command(connection,null,"SELECT * FROM dbo.m_student WHERE student_id=@id AND is_deleted=0");
177:         Param(command,"@id",SqlDbType.BigInt,id);
178:         await using var reader = await command.ExecuteReaderAsync(ct);
179:         if(!await reader.ReadAsync(ct)) return null;
180:         var values = Columns.Keys.ToDictionary(key=>key,key=>reader.IsDBNull(reader.GetOrdinal(key))?null:reader[key]);
181:         return Detail(id,Long(reader,"row_version"),values,reader.GetFieldValue<DateTimeOffset>(reader.GetOrdinal("updated_at")),String(reader,"updated_by")!);
182:     }
183:     private static StudentDetail Detail(long id,long version,Dictionary<string,object?> values,DateTimeOffset updated,string actor)
184:     {
185:         string? S(string key)=>values[key]?.ToString();
186:         DateOnly D(string key)=>values[key] is DateOnly date?date:DateOnly.FromDateTime((DateTime)values[key]!);
187:         var draft = new StudentDraft {
188:             StudentNo=S("student_no")!,StudentName=S("student_name")!,StudentNameKana=S("student_name_kana")!,BirthDateInput=JapaneseDateService.ToInput(D("birth_date")),
189:             GenderCode=S("gender_code")!,PostalCode=S("postal_code")!,PrefectureCode=S("prefecture_code")!,AddressLine1=S("address_line1")!,AddressLine2=S("address_line2"),
190:             PhoneNumber=S("phone_number"),EmailAddress=S("email_address"),AdmissionDate=D("admission_date").ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),
191:             EnrollmentStatusCode=S("enrollment_status_code")!,EnrollmentEndDate=values["enrollment_end_date"] is null?null:D("enrollment_end_date").ToString("yyyy-MM-dd",CultureInfo.InvariantCulture),
192:             ClassId=(long?)values["class_id"],EmergencyContactName=S("emergency_contact_name"),RelationshipCode=S("relationship_code"),EmergencyPhoneNumber=S("emergency_phone_number"),Remarks=S("remarks")
193:         };
194:         return new(id,version,draft,D("birth_date"),updated,actor);
195:     }
196:     public Task<LookupSet> LookupAsync(CancellationToken ct = default) => LookupAsync(true,ct);
197:     public async Task<LookupSet> LookupAsync(bool includeOccupancy,CancellationToken ct = default)
198:     {
199:         _ = User(); await using var connection = await Open(ct);
200:         await using var tx=(SqlTransaction)await connection.BeginTransactionAsync(IsolationLevel.Snapshot,ct);
201:         var occupied=includeOccupancy ? "(SELECT COUNT(*) FROM dbo.m_student s WHERE s.class_id=c.class_id AND s.is_deleted=0 AND s.enrollment_status_code IN ('01','02'))" : "CONVERT(int,0)";
202:         await using var command=Command(connection,tx,$"""
203:             SELECT c.category_id,c.code_value,c.code_name,c.display_order,
204:                    CONVERT(bit,CASE WHEN c.is_active=1 AND k.is_active=1 THEN 1 ELSE 0 END) is_active,c.valid_from,c.valid_to,c.is_protected
205:               FROM dbo.m_code c JOIN dbo.m_code_category k ON k.category_id=c.category_id ORDER BY c.category_id,c.display_order,c.code_value;
206:             SELECT c.*, {occupied} occupied
207:               FROM dbo.m_class c LEFT JOIN dbo.m_code g ON g.category_id=c.grade_category AND g.code_value=c.grade_code
208:              ORDER BY c.school_year DESC,g.display_order,c.display_order,c.class_code,c.class_id;
209:             """);
